actions.command:
cat > /tmp/probe.py <<'PY'
import subprocess, json, os, shutil, sys, pathlib
BIN="/workspace/executable"
def probe(filename, content, extra=[]):
    d="/tmp/probe_dir"
    shutil.rmtree(d, ignore_errors=True); os.makedirs(d)
    p=os.path.join(d, filename)
    os.makedirs(os.path.dirname(p), exist_ok=True)
    mode='wb' if isinstance(content, bytes) else 'w'
    with open(p, mode) as f: f.write(content)
    r=subprocess.run([BIN,"--no-cocomo","--by-file","-f","json"]+extra+[d], capture_output=True, text=True)
    if r.returncode!=0:
        print("ERR", r.returncode, r.stdout, r.stderr); return
    try:
        data=json.loads(r.stdout)
    except:
        print("BADJSON", r.stdout); return
    if not data:
        print("(no files)"); return
    for lang in data:
        for f in lang['Files']:
            print(f"{lang['Name']}: Lines={f['Lines']} Code={f['Code']} Comment={f['Comment']} Blank={f['Blank']} Complexity={f['Complexity']} Bytes={f['Bytes']} Uloc={f['Uloc']}")
        if not lang['Files']:
            print(f"{lang['Name']}: summary Lines={lang['Lines']} Code={lang['Code']} Comment={lang['Comment']} Blank={lang['Blank']} Complexity={lang['Complexity']}")

if __name__=="__main__":
    pass
PY
