import subprocess, json, os, shutil, sys
BIN="/workspace/executable"
def counts(name, content):
    d="/tmp/probe_dir"; shutil.rmtree(d,ignore_errors=True); os.makedirs(d)
    p=os.path.join(d,name); os.makedirs(os.path.dirname(p),exist_ok=True)
    open(p,'wb').write(content if isinstance(content,bytes) else content.encode())
    r=subprocess.run([BIN,"--no-cocomo","--by-file","-f","json",d],capture_output=True,text=True)
    if r.stdout.strip()=="[]" or not r.stdout.strip():
        return None
    j=json.loads(r.stdout)
    if not j: return None
    f=j[0]['Files'][0]
    return (j[0]['Name'], f['Lines'], f['Code'], f['Comment'], f['Blank'], f['Complexity'])
LINE_CANDS=["//","#","--",";","%","!","'","*","::","REM","rem","// ","# ","-- ","; ","% ","! ","' ","C ","c ","$","dnl","@REM","@rem","//--","##","/*","<!--","(*","{-","#|","--[[","=begin","=comment","__END__","/* ","<!-- "]
BLOCK_PAIRS=[("/*","*/"),("<!--","-->"),("(*","*)"),("{-","-}"),("#|","|#"),("--[[","]]"),("--[[","--]]"),("=begin","=end"),("=begin\n","=end"),("\"\"\"","\"\"\""),("'''","'''"),("#=","=#"),("{#","#}"),("%{","%}"),("/*","*/"),("{-","-}"),("/**","*/"),("<!--","-->"),("/*","*/"),("(*","*)"),("#[[","]]"),("[[","]]"),("/*+","+*/"),("/+","+/"),("{-","-}"),("(*","*)"),("/*","*/"),("<!--","-->"),("#`","`#"),("comment",""),("/*","*/"),("{-","-}"),("(*","*)"),("\"\"\"","\"\"\"")]
def probe_lang(name):
    res=counts(name,"x\n")
    if not res: print(name,"NOCOUNT"); return
    lang=res[0]
    lines=[]
    for cand in LINE_CANDS:
        c=counts(name, f"{cand} comment\ncode\n")
        if c and c[3]>0: # comment count
            typ="line" if c[2]==1 else ("block?" if c[3]==2 else "?")
            lines.append((cand,typ,c))
    blocks=[]
    for a,b in set(BLOCK_PAIRS):
        if not b: continue
        c=counts(name, f"{a} comment {b}\ncode\n{a}\nmid\n{b}\ncode\n")
        if c and c[3]>=1:
            blocks.append((a,b,c))
    print(f"{lang} file={name} line/block candidates:")
    for cand,typ,c in lines: print("  L",repr(cand),typ,c)
    for a,b,c in blocks: print("  B",repr(a),repr(b),c)
if __name__=="__main__":
    for n in sys.argv[1:]: probe_lang(n)
PY
