# ---------- Data structures ----------
class FileJob:
    __slots__=("location","filename","extension","language","possible","symlocation","content","bytes","lines","code","comment","blank","complexity","binary","minified","generated","uloc","hash","line_lengths","uloc_lines","feature_lang","lang_display")
    def __init__(self):
        self.location=""; self.filename=""; self.extension=""; self.language=""; self.possible=[]; self.symlocation=""
        self.content=b""; self.bytes=0; self.lines=0; self.code=0; self.comment=0; self.blank=0; self.complexity=0
        self.binary=False; self.minified=False; self.generated=False; self.uloc=0; self.hash=None
        self.line_lengths=[]; self.uloc_lines=set(); self.feature_lang=""; self.lang_display=""

# ---------- Counting ----------
def count_content(content, feature, calc_complexity=True, uloc_enabled=False):
    # returns dict
    if content==b"":
        lines_list=[]
    else:
        lines_list=content.split(b'\n')
        if content.endswith(b'\n'):
            lines_list=lines_list[:-1]
    if feature is None:
        feature=F()
    line_comments=[t.encode() for t in feature["line"]]
    blocks=[(a.encode(), b.encode()) for a,b in feature["block"]]
    strings=[s.encode() for s in feature["strings"]]
    docstrings=[(a.encode(), b.encode()) for a,b in feature["docstrings"]]
    nested=feature["nested"]
    tokens=[t.encode() for t in feature["tokens"]] if calc_complexity else []
    # sort tokens / comments by length descending for precedence at a position
    line_comments_sorted=sorted(line_comments, key=len, reverse=True)
    blocks_sorted=sorted(blocks, key=lambda x: len(x[0]), reverse=True)
    strings_sorted=sorted(strings, key=len, reverse=True)
    docstrings_sorted=sorted(docstrings, key=lambda x: len(x[0]), reverse=True)

    total_lines=len(lines_list)
    code=comment=blank=complexity=0
    line_lengths=[]
    state="normal"  # normal, block, string, docstring
    block_start=b""; block_end=b""; block_depth=0
    string_delim=b""
    doc_end=b""
    trace_states=[]  # list of (state_number, classification)
    for line in lines_list:
        line_lengths.append(len(line))
        has_code=False; has_comment=False
        if state=="block": has_comment=True
        elif state=="string": has_code=True
        elif state=="docstring": has_comment=True
        i=0; L=len(line)
        # For docstring-at-start pre-check, we need to know prefix; computed on the fly
        while i<L:
            if state=="block":
                has_comment=True
                # nested start?
                if nested and block_start and line[i:i+len(block_start)]==block_start:
                    block_depth+=1; i+=len(block_start); continue
                if block_end and line[i:i+len(block_end)]==block_end:
                    i+=len(block_end); block_depth-=1
                    if block_depth<=0:
                        state="normal"; block_depth=0
                    continue
                i+=1; continue
            elif state=="string":
                has_code=True
                if string_delim!=b"`" and i<L and line[i:i+1]==b"\\":
                    i+=2; continue
                if string_delim and line[i:i+len(string_delim)]==string_delim:
                    i+=len(string_delim); state="normal"; string_delim=b""; continue
                i+=1; continue
            elif state=="docstring":
                has_comment=True
                if doc_end and line[i:i+len(doc_end)]==doc_end:
                    i+=len(doc_end); state="normal"; doc_end=b""; continue
                i+=1; continue
            else: # normal
                # complexity check first? It only occurs at ws boundaries, tokens do not start comment/string generally
                if tokens and (i==0 or line[i-1:i] in (b" ", b"\t", b"\r", b"\x0b", b"\x0c")):
                    # don't count if this position starts a comment/string? tokens are not those, but guard: if char is quote/slash etc, token won't match
                    for tok in tokens:
                        if line[i:i+len(tok)]==tok:
                            complexity+=1; break
                # docstrings check before strings
                matched=False
                # block / line / docstring / string precedence by longest start match at i
                candidates=[]
                for a,b in blocks_sorted:
                    if line[i:i+len(a)]==a: candidates.append((len(a),"block",a,b))
                for a,b in docstrings_sorted:
                    if line[i:i+len(a)]==a: candidates.append((len(a),"docstring",a,b))
                for a in strings_sorted:
                    # string token that equals docstring start should be handled as docstring logic if docstring exists with same start
                    if line[i:i+len(a)]==a: candidates.append((len(a),"string",a,a))
                for a in line_comments_sorted:
                    if line[i:i+len(a)]==a: candidates.append((len(a),"line",a,None))
                if candidates:
                    candidates.sort(key=lambda x: x[0], reverse=True)
                    # special: if docstring and string both same length, prefer docstring decision logic below
                    # Choose longest; if tie between line and block (e.g. -- vs --[[) block longer wins already. If tie line vs block same token (Lua --[[ vs --) already diff.
                    # If multiple types same length, priority block > docstring > string > line ??? Python """ : docstring vs string tie
                    priority={"block":3,"docstring":2,"string":1,"line":4}
                    # Actually line comment "--" vs block "--[[" length diff solved. For tie between string and docstring, we decide later.
                    # Re-sort by length then our preferred type for ties: docstring/string handled together
                    maxlen=candidates[0][0]
                    ties=[c for c in candidates if c[0]==maxlen]
                    types=set(c[1] for c in ties)
                    if "line" in types and len(types)==1:
                        has_comment=True; i=L; matched=True; break
                    if "block" in types:
                        # if also line with same length? block wins
                        chosen=[c for c in ties if c[1]=="block"][0]
                        has_comment=True; state="block"; block_start,block_end=chosen[2],chosen[3]; block_depth=1; i+=len(block_start); matched=True; continue
                    if "docstring" in types:
                        # decide docstring vs string based on prefix before i in line
                        prefix=line[:i].strip()
                        # prefix may be string prefix letters
                        is_prefix_only = (prefix==b"" or re.fullmatch(rb'[A-Za-z]{1,3}', prefix) is not None)
                        chosen=[c for c in ties if c[1]=="docstring"][0]
                        if is_prefix_only:
                            has_comment=True; state="docstring"; doc_end=chosen[3]; i+=len(chosen[2]); matched=True; continue
                        else:
                            # treat as string
                            has_code=True; state="string"; string_delim=chosen[2]; i+=len(chosen[2]); matched=True; continue
                    if "string" in types:
                        chosen=[c for c in ties if c[1]=="string"][0]
                        has_code=True; state="string"; string_delim=chosen[2]; i+=len(chosen[2]); matched=True; continue
                    if "line" in types:
                        has_comment=True; i=L; matched=True; break
                if matched:
                    continue
                # normal char
                cbyte=line[i]
                if cbyte not in (32,9,13,11,12):
                    has_code=True
                i+=1; continue
        # classification
        if has_code:
            code+=1; cls="code"
        elif has_comment:
            comment+=1; cls="comment"
        else:
            blank+=1; cls="blank"
        state_num=1
        if state=="block": state_num=5
        elif state=="string": state_num=8
        elif state=="docstring": state_num=9
        trace_states.append((state_num, cls))
    uloc_lines_set=set()
    file_uloc=0
    if uloc_enabled:
        # based on earlier probing: trim trailing \n from content, split
        if content==b"":
            file_uloc=0
            uloc_lines_set={b""}
        else:
            trimmed=content.rstrip(b"\n")
            # Wait rstrip \n removes trailing newline(s), but lines that are \r remain
            # If trimmed is empty (all newlines), split gives [b""]
            parts=trimmed.split(b"\n") if trimmed!=b"" else [b""]
            s=set(parts)
