# ---------- Gitignore ----------
class IgnorePattern:
    __slots__=("base","pattern","neg","dir_only","regex")
    def __init__(self, base, pattern):
        self.base=base; self.neg=False; self.dir_only=False
        p=pattern
        # strip trailing spaces not escaped
        # comments handled by caller
        if p.startswith("!"):
            self.neg=True; p=p[1:]
        elif p.startswith("\\!"):
            p=p[1:]
        if p.startswith("\\#"):
            p=p[1:]
        if p.endswith("/") and not p.endswith("\\/"):
            self.dir_only=True; p=p[:-1]
        self.pattern=p
        self.regex=self._to_regex(p)
    def _to_regex(self, p):
        # translate gitignore pattern to regex matching relative path (posix)
        # If pattern contains slash (not trailing), anchored to base; else match any basename component
        anchored = "/" in p
        if p.startswith("/"):
            p=p[1:]; anchored=True
        # build
        i=0; out=""
        while i<len(p):
            c=p[i]
            if c=="*":
                if i+1<len(p) and p[i+1]=="*":
                    # **
                    # skip **/
                    if i+2<len(p) and p[i+2]=="/":
                        out+="(?:[^/]+/)*"; i+=3; continue
                    else:
                        out+=".*"; i+=2; continue
                else:
                    out+="[^/]*"; i+=1; continue
            elif c=="?":
                out+="[^/]"; i+=1; continue
            elif c=="[":
                j=i+1
                if j<len(p) and p[j]=="!": j+=1
                if j<len(p) and p[j]=="]": j+=1
                while j<len(p) and p[j]!="]": j+=1
                if j>=len(p):
                    out+="\\["; i+=1; continue
                stuff=p[i+1:j]
                if stuff.startswith("!"): stuff="^"+stuff[1:]
                out+="["+stuff+"]"; i=j+1; continue
            elif c=="\\":
                if i+1<len(p): out+=re.escape(p[i+1]); i+=2; continue
                else: out+="\\\\"; i+=1; continue
            else:
                out+=re.escape(c); i+=1; continue
        if anchored:
            regex="^"+out+"(?:/.*)?$"
        else:
            regex="(?:^|/)"+out+"(?:/.*)?$"
        # For dir_only etc caller handles
        try:
