            pass
        return bool(self.regex.search(rel_path))

class IgnoreStack:
    def __init__(self):
        self.patterns=[]  # list of IgnorePattern in order applied
    def add_file(self, base_dir, filepath, enabled=True):
        if not enabled: return
        try:
            with open(filepath,'rb') as f: data=f.read()
        except: return
        try: text=data.decode('utf-8', errors='surrogateescape')
        except: text=""
        for raw in text.splitlines():
            line=raw.rstrip("\r\n")
            if not line.strip(): continue
            if line.startswith("#"): continue
            # trailing spaces strip unless escaped - simple rstrip
            line=line.rstrip()
            if not line: continue
            self.patterns.append(IgnorePattern(base_dir, line))
    def is_ignored(self, abspath, is_dir, roots):
        # Need to determine which patterns apply: pattern base is a directory; rel path from base to abspath
        ignored=False
        # abspath may outside base? skip
        for pat in self.patterns:
            base=pat.base
            # compute rel
            try:
                rel=os.path.relpath(abspath, base)
            except: continue
            if rel.startswith(".."): continue
            rel_posix=rel.replace(os.sep,"/")
            if rel_posix==".": continue
            if pat.matches(rel_posix, is_dir):
                ignored= not pat.neg
        return ignored

