    # returns True if original would panic
    proj=opts.get("cocomo-project-type","organic")
    if not isinstance(proj,str): return False
    if "," in proj: return False
    low=proj.lower()
    if low in ("organic","semi-detached","embedded") and proj!=low:
        # formats that compute cocomo
        if format_name in ("tabular","wide","json2","html","html-table","sql","sql-insert"):
            return True
    return False

def print_cocomo_panic():
    sys.stderr.write("panic: runtime error: index out of range [1] with length 0\n\n")
    sys.stderr.write("goroutine 1 [running]:\n")
    sys.stderr.write("github.com/boyter/scc/v3/processor.EstimateEffort(0x0, 0x3ff0000000000000)\n")
    sys.stderr.write("\tgithub.com/boyter/scc/v3/processor/cocomo.go:36 +0xd3\n")
    # simplified stack
