    if len(path)>limit:
        return "~"+path[-(limit-1):]
    return path

def make_row(label, values, ends, width):
    # values list of strings aligned to ends
    size=max(width, ends[-1] if ends else len(label))
    arr=[" "]*size
    for i,ch in enumerate(label):
        if i < len(arr): arr[i]=ch
        else: arr.append(ch)
    for val,end in zip(values, ends):
        start=end-len(val)
        if start<0:
            # extend left? just set
