    supported_versions=["2024-11-05","2025-03-26","2025-06-18","2025-11-25"]
    out=sys.stdout
    for raw_line in sys.stdin:
        line=raw_line.strip()
        if line=="":
            out.write(json.dumps({"jsonrpc":"2.0","id":None,"error":{"code":-32700,"message":"Parse error"}}, separators=(',',':'))+"\n"); out.flush(); continue
        try:
            req=json.loads(line)
        except:
            out.write(json.dumps({"jsonrpc":"2.0","id":None,"error":{"code":-32700,"message":"Parse error"}}, separators=(',',':'))+"\n"); out.flush(); continue
        if not isinstance(req, dict):
            out.write(json.dumps({"jsonrpc":"2.0","id":None,"error":{"code":-32700,"message":"Parse error"}}, separators=(',',':'))+"\n"); out.flush(); continue
        # notification check: no id key
        has_id="id" in req
        req_id=req.get("id")
        if req.get("jsonrpc")!="2.0":
            if not has_id or req_id is None:
                # still respond? Original for id=1 without jsonrpc responded error
                if not has_id:
                    continue
            out.write(json.dumps({"jsonrpc":"2.0","id":req_id,"error":{"code":-32600,"message":"Invalid JSON-RPC version"}}, separators=(',',':'))+"\n"); out.flush(); continue
        if not has_id or req_id is None:
            # notification - no response
            continue
        method=req.get("method","")
        params=req.get("params",{}) if isinstance(req.get("params",{}), dict) else {}
        def send_result(result):
            out.write(json.dumps({"jsonrpc":"2.0","id":req_id,"result":result}, separators=(',',':'))+"\n"); out.flush()
        def send_error(code,msg):
            out.write(json.dumps({"jsonrpc":"2.0","id":req_id,"error":{"code":code,"message":msg}}, separators=(',',':'))+"\n"); out.flush()
        if method=="initialize":
            pv=params.get("protocolVersion") if isinstance(params,dict) else None
            if pv not in supported_versions:
                pv="2025-11-25"
            send_result({"protocolVersion":pv,"capabilities":{"tools":{}},"serverInfo":{"name":"scc","version":VERSION}})
        elif method=="ping":
            send_result({})
        elif method=="tools/list":
            send_result({"tools":MCP_TOOLS})
        elif method=="tools/call":
            # params may be non-dict in weird cases - original SDK handles
            p=req.get("params",{})
            if not isinstance(p,dict): p={}
            tool_name=p.get("name")
            if tool_name!="analyze":
                send_error(-32602, f"tool '{tool_name}' not found: tool not found"); continue
            args=p.get("arguments",{})
            if args is None: args={}
            text,is_error=mcp_analyze(args)
            result={"content":[{"type":"text","text":text}]}
            if is_error: result["isError"]=True
            send_result(result)
        elif method=="resources/list":
            send_error(-32601, "resources not supported")
        elif method=="prompts/list":
            send_error(-32601, "prompts not supported")
        elif method.startswith("resources/"):
            send_error(-32601, "resources not supported")
        elif method.startswith("prompts/"):
            send_error(-32601, "prompts not supported")
        else:
            send_error(-32601, f"Method {method} not found")
    return 0

