{"command":"cat > /tmp/probe_all.py <<'PY'
import subprocess, json, os, shutil, re, collections, sys
BIN="/workspace/executable"
langs=[]
for line in open('/tmp/langs.txt'):
    m=re.match(r'^(.*) \((.*)\)$', line.strip())
    if m: langs.append((m.group(1), m.group(2).split(',')))
ext2=collections.defaultdict(list)
for n,es in langs:
    for e in es: ext2[e.lower()].append(n)

LINE_CANDS=["//","#","--",";","%","!","'","*","::","REM","rem","dnl","/*","<!--","(*","{-","#|","=begin","=pod","__END__","C","$","// ","##","-- ","; ","% ","' ","\"\"\"","'''","{-","(*","/*","<!--"]
# dedup preserve
LINE_CANDS=list(dict.fromkeys(LINE_CANDS))
BLOCK_PAIRS=[("/*","*/"),("<!--","-->"),("(*","*)"),("{-","-}"),("#|","|#"),("--[[","]]"),("#=","=#"),("=begin","=end"),("=pod","=cut"),('"""','"""'),("'''","'''"),("{#","#}"),("%{","%}"),("{","}"),("#[[","]]"),("[[","]]"),("/**","*/"),("--[[","--]]"),("=comment","=cut"),("/*","*/"),("{-","-}"),("(*","*)")]
BLOCK_PAIRS=list(dict.fromkeys(BLOCK_PAIRS))
WORDS=["if","else","elif","elsif","unless","for","foreach","forall","while","until","loop","switch","case","when","catch","try","finally","except","match","guard","select","do","and","or","not","then","function","raise","rescue","ensure","begin","repeat","elsif","foreach","where","with","assert","yield","await","throw","throws","in","is","return","break","continue","goto","check","forall","exist","all"]
WORDS=list(dict.fromkeys(WORDS))

def representative(name, exts):
    for token in exts:
        low=token.lower()
        if ext2[low]==[name]:
            if low.startswith("."):
                return token  # filename as token (original case? token lower, file lower works for most dotfiles like .bashrc)
            elif "." in low:
                return "probe."+low
            else:
                return "probe."+low
    return None

def run_batch(base, files):
    # files: dict subdir_name -> (repname, content)
    shutil.rmtree(base, ignore_errors=True); os.makedirs(base)
    for sub,(rep,content) in files.items():
        d=os.path.join(base, sub); os.makedirs(d)
        open(os.path.join(d,rep),'w').write(content)
    r=subprocess.run([BIN,"--no-cocomo","--by-file","-f","json",base],capture_output=True,text=True)
    if not r.stdout.strip() or r.stdout.strip()=="[]": return {}
    try: j=json.loads(r.stdout)
    except: print("json fail",r.stdout[:500]); return {}
    out={}
    for lang in j:
        for f in lang['Files']:
            # location .../p<idx>/rep
            parts=f['Location'].split("/")
            sub=parts[-2]
            out[sub]=(lang['Name'], f['Lines'], f['Code'], f['Comment'], f['Blank'], f['Complexity'])
    return out

results={}
todo=[]
for name,exts in langs:
    rep=representative(name, exts)
    if rep is None: continue
    todo.append((name,rep))
print("todo",len(todo))
for idx,(name,rep) in enumerate(todo):
    if idx%50==0: print(idx,name)
    base=f"/tmp/autoprobe_{idx}"
    # line/block batch
    files={}
    for i,cand in enumerate(LINE_CANDS):
        files[f"L{i}"]=(rep, f"{cand} comment\ncode\n")
    for i,(a,b) in enumerate(BLOCK_PAIRS):
        files[f"B{i}"]=(rep, f"{a}\nmid\n{b}\ncode\n")
    res=run_batch(base, files)
    # verify representative yields expected name for at least a code file? Check any result name==name
    names=set(v[0] for v in res.values())
    if name not in names:
        # representative failed (maybe file ignored etc)
        continue
    line_tokens=[]
    for i,cand in enumerate(LINE_CANDS):
        v=res.get(f"L{i}")
        if v and v[0]==name and v[3]==1 and v[2]==1: line_tokens.append(cand)
    blocks=[]
    for i,(a,b) in enumerate(BLOCK_PAIRS):
        v=res.get(f"B{i}")
        if v and v[0]==name and v[3]==3 and v[2]==1: blocks.append((a,b))
    # complexity batch
    files2={}
    for wi,w in enumerate(WORDS):
        files2[f"W{wi}_sp"]=(rep, f"{w} x\n")
        files2[f"W{wi}_pa"]=(rep, f"{w}(x)\n")
        files2[f"W{wi}_br"]=(rep, f"{w}{{\n")
        files2[f"W{wi}_co"]=(rep, f"{w}:\n")
        files2[f"W{wi}_lp"]=(rep, f"({w} x\n")
    files2["S_and"]=(rep,"x && y\n"); files2["S_or"]=(rep,"x || y\n"); files2["S_q"]=(rep,"x ? y\n")
    res2=run_batch(base, files2)
    tokens=[]
    for wi,w in enumerate(WORDS):
        if res2.get(f"W{wi}_sp",(None,0,0,0,0,0))[5]>0: tokens.append(w+" ")
        if res2.get(f"W{wi}_pa",(None,0,0,0,0,0))[5]>0: tokens.append(w+"(")
        if res2.get(f"W{wi}_br",(None,0,0,0,0,0))[5]>0: tokens.append(w+"{")
        if res2.get(f"W{wi}_co",(None,0,0,0,0,0))[5]>0: tokens.append(w+":")
        if res2.get(f"W{wi}_lp",(None,0,0,0,0,0))[5]>0 and (w+" ") not in tokens: tokens.append("("+w+" ")
    if res2.get("S_and",(None,0,0,0,0,0))[5]>0: tokens.append("&& ")
    if res2.get("S_or",(None,0,0,0,0,0))[5]>0: tokens.append("|| ")
    if res2.get("S_q",(None,0,0,0,0,0))[5]>0: tokens.append("? ")
    results[name]={"rep":rep,"line_candidates":line_tokens,"blocks":blocks,"tokens":tokens}
    shutil.rmtree(base, ignore_errors=True)
json.dump(results, open("/tmp/probed.json","w"), indent=1)
print("done",len(results))
PY
timeout 1200 python3 /tmp/probe_all.py 2>&1 | tail -n 50"}

