        if res.get(f"W{wi}_co",(0,0,0,0,0,0))[5]>0: tokens.append(w+":")
        if res.get(f"W{wi}_lp",(0,0,0,0,0,0))[5]>0 and (w+" ") not in tokens: tokens.append("("+w+" ")
