import json, pathlib
probed=json.load(open("/tmp/probed.json")); probed2=json.load(open("/tmp/probed2.json")); pstr=json.load(open("/tmp/probed_strings.json")); nested=json.load(open("/tmp/probed_nested.json"))
def minimal(cands):
    kept=[]
    for c in sorted(cands, key=lambda x:(len(x),x)):
        if any(c.startswith(k) for k in kept): continue
        kept.append(c)
    return kept
auto={}
for name,info in probed.items():
    line=[c for c in minimal(info['line_candidates']) if c not in ('"""',"'''")]
    blocks=[]; doc=[]; seen=set()
    allblocks=[tuple(x) for x in info['blocks']] + [tuple(x) for x in probed2.get(name,{}).get("blocks",[])]
    for a,b in allblocks:
        if (a,b) in seen: continue
        seen.add((a,b))
        if a in ('"""',"'''"): doc.append((a,b)); continue
        if a=='/**' and ('/*','*/') in allblocks: continue
        if a=='--[[' and b=='--]]' and ('--[[',']]') in allblocks: continue
        blocks.append((a,b))
    tokens=list(dict.fromkeys(info['tokens'] + probed2.get(name,{}).get("tokens",[])))
    strings=[]; rawset=set(tuple(x) for x in pstr.get(name,[]))
    if ('"','"') in rawset: strings.append('"')
    if ("'","'") in rawset: strings.append("'")
    if ('`','`') in rawset: strings.append('`')
    if '"' not in strings and ('"""','"""') in rawset: strings.append(('"""','"""'))
    if "'" not in strings and ("'''","'''") in rawset: strings.append(("'''","'''"))
    if ('[[',']]') in rawset and (']]','[[') not in rawset: strings.append(('[[',']]'))
    if (']]', '[[') in rawset: strings.append((']]','[['))
    auto[name]={"line":line,"block":blocks,"docstrings":doc,"strings":strings,"tokens":tokens,"nested":bool(nested.get(name,False))}
