p=pathlib.Path("/workspace/scc.py"); t=p.read_text()
start=t.index("AUTO_FEATURES_DATA = ")
end=t.index("\nfor _name,_d in AUTO_FEATURES_DATA.items():", start)
t=t[:start]+chunk.rstrip()+t[end:]
p.write_text(t)
print("regen", len(auto))
